<?php
require_once __DIR__ . '/../database/app/layout.php';
$u=require_role(['admin','restaurant','event_organizer','ngo','demand_reporter']);$pdo=db();
$start=trim((string)($_GET['start']??date('Y-m-01')));$end=trim((string)($_GET['end']??date('Y-m-d')));
if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$start)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$end)||$start>$end){$start=date('Y-m-01');$end=date('Y-m-d');}
$where="sf.status IN ('delivered','completed') AND DATE(COALESCE(d.delivery_time,dr.updated_at)) BETWEEN ? AND ?";$args=[$start,$end];
if($u['role']==='admin'){}elseif(in_array($u['role'],['restaurant','event_organizer'],true)){$where.=' AND sf.restaurant_id=?';$args[]=$u['id'];}else{$where.=' AND dr.requested_by=?';$args[]=$u['id'];}
$q=$pdo->prepare("SELECT COUNT(*) AS food_listings,COALESCE(SUM(x.quantity_kg),0) AS rescued_kg FROM (SELECT DISTINCT sf.id,sf.quantity_kg FROM surplus_food sf JOIN donation_requests dr ON dr.surplus_food_id=sf.id LEFT JOIN deliveries d ON d.donation_request_id=dr.id WHERE $where) x");$q->execute($args);$stats=$q->fetch()?:[];$cq=$pdo->prepare("SELECT COUNT(DISTINCT dr.id) FROM donation_requests dr JOIN surplus_food sf ON sf.id=dr.surplus_food_id LEFT JOIN deliveries d ON d.donation_request_id=dr.id WHERE $where");$cq->execute($args);$stats['completed_requests']=(int)$cq->fetchColumn();
$kg=(float)($stats['rescued_kg']??0);$factor=(float)(getenv('FOODRESCUE_CO2E_KG_PER_KG')?:2.5); // illustrative default; configure with a sourced methodology before formal reporting
$estimated=max(0,$kg*$factor);
page_header('Environmental impact'); ?>
<div class="page-intro"><div class="eyebrow">ENVIRONMENTAL IMPACT</div><h1>Food rescue, <em>measured.</em></h1><p>Summary of completed food rescue records for your account. Estimated emissions are illustrative and depend on the configured factor.</p></div>
<form method="get" class="filter-bar"><label>From <input type="date" name="start" value="<?= e($start) ?>" required></label><label>To <input type="date" name="end" value="<?= e($end) ?>" required></label><button class="btn">Update report</button></form>
<div class="dashboard-stats"><div class="stat-card"><div class="stat-label">Completed listings</div><div class="stat-number"><?= number_format((int)($stats['food_listings']??0)) ?></div></div><div class="stat-card"><div class="stat-label">Recorded rescued quantity</div><div class="stat-number"><?= number_format($kg,2) ?> <small>kg</small></div></div><div class="stat-card"><div class="stat-label">Completed requests</div><div class="stat-number"><?= number_format((int)($stats['completed_requests']??0)) ?></div></div><div class="stat-card"><div class="stat-label">Illustrative CO₂e estimate</div><div class="stat-number"><?= number_format($estimated,2) ?> <small>kg</small></div></div></div>
<div class="notice-panel"><strong>Methodology & limitations</strong><p>The default factor is <?= e((string)$factor) ?> kg CO₂e per kg rescued and is an illustrative placeholder, not a verified Bangladesh-specific lifecycle factor. Set FOODRESCUE_CO2E_KG_PER_KG only after selecting and documenting a credible source. This estimate is not independently audited and should not be represented as certified carbon savings.</p><p>Quantities reflect completed listing records; multi-request or partial-quantity workflows may need reconciliation before using the figure as an audited total.</p></div>
<?php page_footer(); ?>
